head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
*/

scwin.vScrenID = "ULDFIS00200.xml";
///////// 1. 변수 및 선언 영역 /////////
scwin.vKisCd = ""; // 조회조건 기업코드
scwin.vAcntclsDt = ""; // 조회조건 결산일자
scwin.vArray = "";

/**
 *  화면이 최초 로드될때 실행되는 초기화 이벤트
 *  (초기 데이터 조회나 컴포넌트 설정)
 */

///////// 2. 초기화 영역 /////////
scwin.onpageload = function() {
    scwin.init();
};

/**
 *  현재 로딩된 페이지가 초기화되거나 종료될때(다른 화면으로 이동하거나 페이지를 닫기전) 발생하는 이벤트
 *  (주로 SPA(Single Page Application) 환경에서 전역 자원을 해제하거나 메모리 누수 방지)
 */
scwin.onpageunload = function() {
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 *  화면 초기화
 */
scwin.init = function() {

    // 결산일자 조회
    $p.parent().frame_head.getWindow().scwin.fn_SrchAcntclsDt();

};

/**
 *  데이터셋 초기화
 */
scwin.initDs = function() {
    dlt_industryStatusListRes.setData([]);
};

/**
 *  조회조건 유효성 체크
 */
scwin.chkValid = function() {

    //필수항목 체크
    scwin.vKisCd = $p.parent().frame_head.getWindow().scwin.fn_GetKisCd();
    scwin.vAcntclsDt = $p.parent().frame_head.getWindow().scwin.fn_GetAcntclsDt();

    if (scwin.vKisCd === "" || scwin.vAcntclsDt === "") {
        return false;
    }

    return true;

};

/**
 * 업계현황 조회
 */
scwin.search = async function() {

    //데이터셋 초기화
    scwin.initDs();

    // 조회조건 체크
    if (!scwin.chkValid()) {
        return;
    }

    dma_industryStatusInfoReq.set("kisCd", vKisCd); // 기업코드
    dma_industryStatusInfoReq.set("acntclsDt", vAcntclsDt); // 결산일자

    const sbmOptions = {
        id : "sbm_industryStatus",
        action : "/api/listing/nice/company-status/industry-status",
        method : "get",
        ref : "dma_industryStatusInfoReq",
        target : "dlt_industryStatusListRes|append",
        isProcessMsg : false
    };
    const res = await await $c.sbm.executeDynamic(sbmOptions);
    dlt_industryStatusListRes.setJSON(res.responseJSON.body);

    scwin.appendContents();

};

/**
 * 업계현황 정보 생성
 */
scwin.appendContents = function() {

    let strContent = "<div style='overflow-x:hidden;overflow-y:scroll;width:100%;height:575px;font-family:돋움체;'>";

    for (let nRow = 0; nRow < dlt_industryStatusListRes.getRowCount(); nRow++) {
        strContent = strContent + dlt_industryStatusListRes.getCellData(nRow, "ctnt");
    }

    strContent = strContent + "</div>";
    const tbxIndustryStatusObj = $p.getComponentById("tbx_industryStatus").render;
    tbxIndustryStatusObj.innerHTML = strContent;
    tbx_industryStatus.setStyle("border", "1px solid blue");

};
